//! Generated files of a profile: client build headers (og_modules.h, og_profile.h, og_modules.mk, resource script),
//! the server config (conf/import/odinguard_conf.txt, secrets env file) and the command reference.

use std::fmt::Write as _;
use std::path::Path;

use crate::profile::Profile;
use crate::registry::Registry;
use crate::{Error, Result};

/// Values derived from the profile and its secrets.
pub struct Derived {
    pub server_seed: [u8; 32],
    pub server_pub: [u8; 32],
    pub build_secret: [u8; 32],
    pub proto_salt: [u8; 16],
    pub tag: [u8; 16],
    pub mask: [u8; 32],
}

impl Derived {
    pub fn new(p: &Profile, server_seed: [u8; 32], build_secret: [u8; 32]) -> Result<Self> {
        let seed = hex::decode(&p.general.variation_seed).map_err(|_| Error::Invalid("variation_seed".into()))?;
        let server_pub = crate::crypto::public_key(&server_seed);
        let mut m = b"OdinGuard/proto-salt".to_vec();
        m.extend_from_slice(&seed);
        m.extend_from_slice(&server_pub);
        let proto_salt: [u8; 16] = crate::crypto::blake2b(&m);
        let mut t = b"OdinGuard/tag".to_vec();
        t.extend_from_slice(&proto_salt);
        let tag: [u8; 16] = crate::crypto::blake2b(&t);
        let mut k = b"OdinGuard/mask".to_vec();
        k.extend_from_slice(&seed);
        k.extend_from_slice(p.general.id.as_bytes());
        let mask: [u8; 32] = crate::crypto::blake2b(&k);
        Ok(Derived { server_seed, server_pub, build_secret, proto_salt, tag, mask })
    }
}

fn c_bytes(b: &[u8]) -> String {
    let parts: Vec<String> = b.iter().map(|x| format!("0x{x:02x}")).collect();
    format!("{{{}}}", parts.join(","))
}

fn masked(v: &[u8], mask: &[u8; 32]) -> Vec<u8> {
    v.iter().enumerate().map(|(i, b)| b ^ mask[i & 31]).collect()
}

fn c_string(s: &str) -> String {
    s.chars().filter(|c| !c.is_control()).map(|c| if c == '"' || c == '\\' { format!("\\{c}") } else { c.to_string() }).collect()
}

/// Protected files of the file-range challenge (index = position, same list in client and server).
pub fn protected_files(p: &Profile) -> Vec<(&'static str, bool)> {
    let mut v = vec![("odin.grf", true)];
    if p.modules.iter().any(|m| m == "competitive-pack") {
        v.push(("odin-dark.grf", false));
    }
    v
}

/// Folder names (last path component) of the kept previous releases, as they are copied to `<ref_dir>/previous/`.
pub fn previous_names(p: &Profile) -> Vec<String> {
    p.rollout
        .previous_releases
        .iter()
        .filter_map(|r| std::path::Path::new(r.trim_end_matches('/')).file_name().map(|n| n.to_string_lossy().into_owned()))
        .collect()
}

/// Client sources of the selected modules in a profile-specific order (build variation: different code layout).
pub fn client_sources(p: &Profile, reg: &Registry) -> Vec<String> {
    let seed = hex::decode(&p.general.variation_seed).unwrap_or_default();
    let mut src: Vec<String> = reg
        .modules
        .iter()
        .filter(|m| p.modules.contains(&m.id))
        .flat_map(|m| m.client_src.iter().cloned())
        .collect();
    src.sort_by_key(|f| {
        let mut m = seed.clone();
        m.extend_from_slice(f.as_bytes());
        crate::crypto::blake2b::<8>(&m)
    });
    src
}

pub fn modules_h(p: &Profile, reg: &Registry) -> String {
    let mut s = String::from("/* Generated by the OdinGuard Studio. Do not edit. */\n#ifndef OG_MODULES_H\n#define OG_MODULES_H\n");
    for m in &reg.modules {
        if let Some(d) = &m.define {
            let _ = writeln!(s, "#define {d} {}", u8::from(p.modules.contains(&m.id)));
        }
    }
    s.push_str("#endif\n");
    s
}

pub fn modules_mk(p: &Profile, reg: &Registry) -> String {
    let files: Vec<String> = client_sources(p, reg).iter().map(|f| if f.starts_with("..") { f.trim_start_matches("../").to_string() } else { format!("src/{f}") }).collect();
    let files: Vec<String> = files.into_iter().map(|f| if f.starts_with("proto/") { format!("../{f}") } else { f }).collect();
    format!("# Generated by the OdinGuard Studio (module selection and link order of the profile).\nOG_SRC := {}\n", files.join(" "))
}

pub fn profile_h(p: &Profile, d: &Derived) -> String {
    let salt = p.general.hwid_salt.as_bytes();
    let files = protected_files(p);
    let names: Vec<String> = files.iter().map(|(f, _)| format!("\"{f}\"")).collect();
    let ports: Vec<String> = p.general.ports.iter().map(u16::to_string).collect();
    let variation = u32::from_le_bytes([d.mask[0], d.mask[1], d.mask[2], d.mask[3]]);
    format!(
        "/* Generated by the OdinGuard Studio for profile '{id}'. Secrets are masked. Do not edit. */\n\
#ifndef OG_PROFILE_H\n#define OG_PROFILE_H\n\
#define OG_PROFILE_ID \"{id}\"\n\
#define OG_PROFILE_OPERATOR \"{op}\"\n\
#define OG_PROFILE_BUILD \"{build}\"\n\
#define OG_PROFILE_PORTS \"{ports}\"\n\
#define OG_PROFILE_SPLASH_MS {splash}\n\
#define OG_PROFILE_VARIATION 0x{variation:08x}u\n\
#define OG_PROFILE_MASK {mask}\n\
#define OG_PROFILE_HWID_SALT_LEN {salt_len}\n\
#define OG_PROFILE_HWID_SALT {salt}\n\
#define OG_PROFILE_PROTO_SALT {proto}\n\
#define OG_PROFILE_BUILD_SECRET {secret}\n\
#define OG_PROFILE_FILES {{{files}}}\n\
#define OG_PROFILE_NFILES {nfiles}\n\
#define OG_PROFILE_SERVER_PUBKEY {pubkey}\n\
#endif\n",
        id = c_string(&p.general.id),
        op = c_string(&p.general.operator),
        build = c_string(&p.general.client_build),
        ports = ports.join(","),
        splash = if p.modules.iter().any(|m| m == "branding") { p.general.splash_ms } else { 0 },
        mask = c_bytes(&d.mask),
        salt_len = salt.len(),
        salt = c_bytes(&masked(salt, &d.mask)),
        proto = c_bytes(&masked(&d.proto_salt, &d.mask)),
        secret = c_bytes(&masked(&d.build_secret, &d.mask)),
        files = names.join(", "),
        nfiles = files.len(),
        pubkey = c_bytes(&d.server_pub),
    )
}

pub fn resource_rc(p: &Profile) -> String {
    let splash = if p.modules.iter().any(|m| m == "branding") { "100 BITMAP \"splash.bmp\"\n" } else { "" };
    format!(
        "#include <winver.h>\n#include \"og_version.h\"\n#include \"og_profile.h\"\n\n1 ICON \"odinguard.ico\"\n{splash}\n\
VS_VERSION_INFO VERSIONINFO\nFILEVERSION OG_VER_MAJOR, OG_VER_MINOR, OG_VER_PATCH, 0\nPRODUCTVERSION OG_VER_MAJOR, OG_VER_MINOR, OG_VER_PATCH, 0\n\
FILEOS VOS_NT_WINDOWS32\nFILETYPE VFT_DLL\nBEGIN\n    BLOCK \"StringFileInfo\"\n    BEGIN\n        BLOCK \"040904B0\"\n        BEGIN\n\
            VALUE \"CompanyName\", OG_PROFILE_OPERATOR\n            VALUE \"FileDescription\", \"OdinGuard Anti Cheat\"\n\
            VALUE \"FileVersion\", OG_VERSION_STR\n            VALUE \"InternalName\", \"odinguard\"\n\
            VALUE \"LegalCopyright\", \"OdinGuard Anti Cheat\"\n            VALUE \"OriginalFilename\", \"odinguard.dll\"\n\
            VALUE \"ProductName\", \"OdinGuard Anti Cheat\"\n            VALUE \"ProductVersion\", OG_VERSION_STR\n        END\n    END\n\
    BLOCK \"VarFileInfo\"\n    BEGIN\n        VALUE \"Translation\", 0x0409, 1200\n    END\nEND\n"
    )
}

fn conf_value(v: &toml::Value) -> String {
    match v {
        toml::Value::Boolean(b) => if *b { "yes".into() } else { "no".into() },
        toml::Value::String(s) => s.clone(),
        other => other.to_string(),
    }
}

/// Server config of the profile (goes to conf/import/odinguard_conf.txt). Secrets are not in it, they go to the env
/// file (ODINGUARD_KEY, ODINGUARD_PROTO_SALT, ODINGUARD_BUILD_SECRET).
/// `built`: GRFs of the release (odin.grf, odin-dark.grf) that are added to the GRF manifest automatically.
/// `og_min_release` of the server config: see `Rollout::min_release`
pub fn min_release(p: &Profile) -> String {
    match p.rollout.min_release.trim() {
        "" if p.rollout.previous_releases.is_empty() => crate::guard_release(),
        "" | "off" | "none" => "0".into(),
        v => v.to_string(),
    }
}

pub fn server_conf(p: &Profile, reg: &Registry, sigpack_key: &[u8; 32], built: &[crate::profile::GrfFile], ref_dir: &str) -> String {
    let mut s = format!(
        "// Generated by the OdinGuard Studio for profile '{}' (rollout stage {}). Edit the profile, not this file.\n\
// Secrets come from the environment (secrets/odinguard.env): ODINGUARD_KEY, ODINGUARD_PROTO_SALT, ODINGUARD_BUILD_SECRET.\n",
        p.general.id, p.rollout.stage
    );
    let _ = writeln!(s, "og_enable: yes");
    let _ = writeln!(s, "og_log_only: {}", if p.rollout.stage == 1 { "yes" } else { "no" });
    let required = p.rollout.stage >= 4 || p.param(reg, "core", "required").and_then(|v| v.as_bool()) == Some(true);
    let _ = writeln!(s, "og_required: {}", if required { "yes" } else { "no" });
    let _ = writeln!(s, "og_min_release: {}", min_release(p));
    if p.modules.iter().any(|m| m == "competitive-pack") && !p.assets.competitive_enforce.is_empty() {
        let _ = writeln!(s, "\n// the competitive pack is required on these competitive maps (assets.competitive_enforce)");
        let _ = writeln!(s, "og_dark_enforce: {}", p.assets.competitive_enforce.join(","));
    }
    s.push_str("\n// modules\n");
    for m in &reg.modules {
        let on = p.modules.contains(&m.id);
        if let Some(k) = &m.server_key
            && k != "og_enable"
        {
            let _ = writeln!(s, "{k}: {}", if on { "yes" } else { "no" });
        }
        if !on {
            continue;
        }
        for prm in &m.params {
            let Some(conf) = &prm.conf else { continue };
            if (m.id == "core" && (prm.name == "required" || prm.name == "log_only")) || (m.kind == "challenge" && prm.name == "enabled") {
                continue;
            }
            if let Some(v) = p.param(reg, &m.id, &prm.name) {
                let _ = writeln!(s, "{conf}: {}", conf_value(&v));
            }
        }
    }
    s.push_str("\n// references (copied by the server package)\n");
    if p.modules.iter().any(|m| m == "integrity") {
        let _ = writeln!(s, "og_guard_file: {ref_dir}/odinguard.dll");
        for r in previous_names(p) {
            let _ = writeln!(s, "og_guard_previous_file: {ref_dir}/previous/{r}/odinguard.dll");
        }
    }
    for (i, (f, req)) in protected_files(p).iter().enumerate() {
        let _ = writeln!(s, "og_protected_file: {i},{ref_dir}/{f},{}", if *req { "yes" } else { "no" });
        for r in previous_names(p) {
            let _ = writeln!(s, "og_protected_previous: {i},{ref_dir}/previous/{r}/{f}");
        }
    }
    if p.modules.iter().any(|m| m == "cheat-signatures") {
        let _ = writeln!(s, "og_sigpack: {ref_dir}/odinguard.sigpack\nog_sigpack_key: {}\nog_sigpack_min_version: {}", hex::encode(sigpack_key), p.signatures.version);
    }
    s.push_str("\n// commands\n");
    for c in &reg.commands {
        let set = p.commands.get(&c.id).cloned().unwrap_or_default();
        let enabled = p.commands.get(&c.id).is_none_or(|x| x.enabled) && p.modules.contains(&c.module);
        let _ = writeln!(s, "og_cmd_{}: {}", c.id, if enabled { "yes" } else { "no" });
        let _ = writeln!(s, "og_cmdgroup_{}: {}", c.id, set.group.unwrap_or(c.group));
        let _ = writeln!(s, "og_cmdrate_{}: {}", c.id, set.rate_ms.unwrap_or(c.rate_ms));
        if let Some(n) = &set.name
            && c.kind == "client"
        {
            let _ = writeln!(s, "og_cmdname_{}: {n}", c.id);
        }
    }
    if p.modules.iter().any(|m| m == "grf-rules") {
        s.push_str("\n// GRF manifest (og grf-scan); several lines per name = accepted versions during a patch rollout\n");
        let _ = writeln!(s, "og_grf_modified_action: {}", p.grf.modified_action);
        let _ = writeln!(s, "og_grf_unknown_action: {}", p.grf.unknown_action);
        let _ = writeln!(s, "og_grf_missing_action: {}", p.grf.missing_action);
        for f in built.iter().chain(&p.grf.files) {
            let full = if f.full.is_empty() { "-" } else { &f.full };
            let _ = writeln!(s, "og_grf_file: {},{},{},{full},{}", f.name, f.size, f.tail, if f.required { "yes" } else { "no" });
        }
        for m in &p.grf.mods {
            let _ = writeln!(s, "og_grf_mod: {},{}", m.tail, m.note);
        }
        for o in &p.grf.overlays {
            let _ = writeln!(s, "og_grf_overlay: {o}");
        }
    }
    s
}

pub fn secrets_env(d: &Derived) -> String {
    format!(
        "# OdinGuard Anti Cheat server secrets. Keep out of git and out of the client package.\n\
ODINGUARD_KEY={}\nODINGUARD_PROTO_SALT={}\nODINGUARD_BUILD_SECRET={}\n",
        hex::encode(d.server_seed),
        hex::encode(d.proto_salt),
        hex::encode(d.build_secret)
    )
}

/// Command reference in Markdown (players and GMs), language "de" or "en".
pub fn commands_md(p: &Profile, reg: &Registry, lang: &str) -> String {
    let de = lang == "de";
    let mut s = String::new();
    let _ = writeln!(s, "<!-- generated by the OdinGuard Studio from modules/commands.toml and profile '{}' -->", p.general.id);
    for (title, players) in [(if de { "Spieler" } else { "Players" }, true), (if de { "Nur GM" } else { "GM only" }, false)] {
        let _ = writeln!(s, "\n### {title}\n\n| Command | {} |\n|---|---|", if de { "Was es macht" } else { "What it does" });
        for c in &reg.commands {
            let set = p.commands.get(&c.id).cloned().unwrap_or_default();
            if !(p.commands.get(&c.id).is_none_or(|x| x.enabled) && p.modules.contains(&c.module)) {
                continue;
            }
            if (set.group.unwrap_or(c.group) == 0) != players {
                continue;
            }
            let name = set.name.clone().unwrap_or_else(|| c.name.clone());
            let sym = if c.kind == "client" { "!" } else { "@" };
            let params = if c.params.is_empty() { String::new() } else { format!(" {}", c.params) };
            let _ = writeln!(s, "| `{sym}{name}{params}` | {} |", if de { &c.help_de } else { &c.help_en }.replace('|', "\\|"));
        }
    }
    s
}

pub fn write(path: &Path, text: &str) -> Result<()> {
    if let Some(d) = path.parent() {
        std::fs::create_dir_all(d).map_err(|e| Error::Io(d.display().to_string(), e))?;
    }
    std::fs::write(path, text).map_err(|e| Error::Io(path.display().to_string(), e))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn reg() -> Registry {
        Registry::load(&crate::repo_root().join("modules")).unwrap()
    }

    #[test]
    fn minimal_profile_selects_only_core_sources() {
        let r = reg();
        let mut p = Profile::new("min", "Min").unwrap();
        p.modules = vec!["core".into(), "rate-limit".into()];
        let src = client_sources(&p, &r);
        assert!(src.iter().all(|f| r.module("core").unwrap().client_src.contains(f)), "{src:?}");
        let h = modules_h(&p, &r);
        assert!(h.contains("#define OG_MOD_CORE 1") && h.contains("#define OG_MOD_DETECT 0"));
    }

    #[test]
    fn secrets_are_masked_in_the_header() {
        let p = Profile::new("x", "X \"quoted\"").unwrap();
        let d = Derived::new(&p, [1u8; 32], [0xAB; 32]).unwrap();
        let h = profile_h(&p, &d);
        assert!(!h.contains(&c_bytes(&[0xAB; 32])), "build secret in clear");
        assert!(h.contains("X \\\"quoted\\\""));
    }

    #[test]
    fn server_conf_follows_rollout_stage_and_commands() {
        let r = reg();
        let mut p = Profile::new("x", "X").unwrap();
        p.rollout.stage = 4;
        p.commands.insert("lgp".into(), crate::profile::CommandSetting { enabled: false, ..Default::default() });
        p.commands.insert("ping".into(), crate::profile::CommandSetting { enabled: true, name: Some("latency".into()), ..Default::default() });
        p.grf.files.push(crate::profile::GrfFile { name: "data.grf".into(), size: 9, tail: "a".repeat(64), full: String::new(), required: true });
        p.grf.mods.push(crate::profile::GrfMod { tail: "b".repeat(64), note: "darkworld".into() });
        p.rollout.previous_releases.push("previous-releases/0123456789ab".into());
        let c = server_conf(&p, &r, &[0; 32], &[], "conf/odinguard");
        assert!(c.contains("og_guard_previous_file: conf/odinguard/previous/0123456789ab/odinguard.dll"), "the old guard stays accepted during a rollout");
        assert!(c.contains("og_protected_previous: 0,conf/odinguard/previous/0123456789ab/odin.grf"), "so does the old odin.grf");
        assert!(c.contains(&format!("og_grf_file: data.grf,9,{},-,yes", "a".repeat(64))));
        assert!(c.contains(&format!("og_grf_mod: {},darkworld", "b".repeat(64))));
        assert!(c.contains("og_log_only: no") && c.contains("og_required: yes"));
        assert!(c.contains("og_min_release: 0\n"), "a soft rollout lets older releases in");
        p.rollout.previous_releases.clear();
        let c = server_conf(&p, &r, &[0; 32], &[], "conf/odinguard");
        assert!(c.contains(&format!("og_min_release: {}\n", crate::guard_release())), "by default only the built release logs in");
        assert!(crate::guard_release().starts_with("1."));
        p.rollout.min_release = "1.0.0".into();
        assert!(server_conf(&p, &r, &[0; 32], &[], "conf/odinguard").contains("og_min_release: 1.0.0\n"));
        assert!(c.contains("og_cmd_lgp: no") && c.contains("og_cmdname_ping: latency"));
        assert!(c.contains("og_rate_limit: no"), "rate-limit is not in the default set");
        let md = commands_md(&p, &r, "de");
        assert!(md.contains("`!latency`") && !md.contains("`@lgp`") && !md.contains("`@lgp ["));
    }
}
